-- Modify "kyc_applications" table
ALTER TABLE "seller"."kyc_applications" DROP CONSTRAINT "kyc_applications_complete_check", ADD CONSTRAINT "kyc_applications_complete_check" CHECK ((status <> ALL (ARRAY['SUBMITTED'::text, 'APPROVED'::text, 'REJECTED'::text])) OR ((submitted_at IS NOT NULL) AND ((pii_purged_at IS NOT NULL) OR ((real_name IS NOT NULL) AND (english_name IS NOT NULL) AND (bank_name IS NOT NULL) AND (bank_code IS NOT NULL) AND (bank_account_enc IS NOT NULL) AND (contact_email IS NOT NULL) AND (contact_phone IS NOT NULL) AND (((seller_type = 'INDIVIDUAL'::text) AND (id_card_no_enc IS NOT NULL)) OR ((seller_type = 'COMPANY'::text) AND (company_name IS NOT NULL) AND (tax_id IS NOT NULL) AND (rep_id_card_no_enc IS NOT NULL))))))), ADD CONSTRAINT "kyc_applications_purged_check" CHECK ((pii_purged_at IS NULL) OR ((real_name IS NULL) AND (birth_date IS NULL) AND (id_card_no_enc IS NULL) AND (id_card_hash IS NULL) AND (id_card_hash_key IS NULL) AND (id_card_issue_date IS NULL) AND (id_card_issue_type IS NULL) AND (id_card_issue_location IS NULL) AND (english_name IS NULL) AND (bank_name IS NULL) AND (bank_code IS NULL) AND (bank_account_enc IS NULL) AND (bank_account_hash IS NULL) AND (bank_account_hash_key IS NULL) AND (website_url IS NULL) AND (contact_email IS NULL) AND (contact_phone IS NULL) AND (company_name IS NULL) AND (tax_id IS NULL) AND (tax_id_hash IS NULL) AND (tax_id_hash_key IS NULL) AND (company_register_date IS NULL) AND (company_town_code IS NULL) AND (company_address_detail IS NULL) AND (company_phone IS NULL) AND (rep_id_card_no_enc IS NULL) AND (rep_id_card_hash IS NULL) AND (rep_id_card_hash_key IS NULL))), ADD COLUMN "pii_purged_at" timestamptz NULL;
-- Modify "payuni_registrations" table
ALTER TABLE "seller"."payuni_registrations" ADD CONSTRAINT "payuni_registrations_purged_check" CHECK (((pii_purged_at IS NULL) AND (contact_name IS NOT NULL) AND (contact_mobile IS NOT NULL) AND (mer_email IS NOT NULL)) OR ((pii_purged_at IS NOT NULL) AND (contact_name IS NULL) AND (contact_mobile IS NULL) AND (contact_tel IS NULL) AND (mer_email IS NULL) AND (mer_tel IS NULL) AND (reason IS NULL))), ALTER COLUMN "contact_name" DROP NOT NULL, ALTER COLUMN "contact_mobile" DROP NOT NULL, ALTER COLUMN "mer_email" DROP NOT NULL, ADD COLUMN "pii_purged_at" timestamptz NULL;
-- Modify "stores" table
ALTER TABLE "seller"."stores" ADD CONSTRAINT "stores_pii_purged_check" CHECK (((pii_purged_at IS NULL) AND (store_name IS NOT NULL)) OR ((pii_purged_at IS NOT NULL) AND (status = 'CLOSED'::text) AND ((pii_purged_at - deleted_at) >= '30 days'::interval) AND (store_name IS NULL) AND (description IS NULL) AND (contact_phone IS NULL) AND (town_code IS NULL) AND (address_detail IS NULL) AND (prize IS NULL) AND (website_url IS NULL) AND (seo_title IS NULL) AND (seo_description IS NULL))), ALTER COLUMN "store_name" DROP NOT NULL, ADD COLUMN "pii_purged_at" timestamptz NULL;
